                : "bg-slate-100 text-slate-700 hover:bg-slate-200"
            }`}
          >
            {label}
          </button>
        ))}
      </div>

      {tab === "deltas" && (
        <div className="space-y-4">
          <ToggleGroup
            label="Show"
            value={deltaFilter}
            options={[
              { id: "all", label: "All metrics" },
